<?php
namespace Tests\Feature;
use App\Imports\{XlsxUsers,UserImports,ConfirmImport};
use App\Domain\Failure;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\{DB,Hash,Queue};
use Illuminate\Support\Str;
use OpenSpout\Common\Entity\{Row,Cell\StringCell,Cell\NumericCell,Cell\FormulaCell};
use OpenSpout\Writer\XLSX\{Writer,Options};
use Tests\TestCase;
use ZipArchive;
final class UsersImportTest extends TestCase {
 use DatabaseTransactions;
 private array $files=[];
 private function sid():string{return '000'.bin2hex(random_bytes(8));}
 protected function tearDown():void{gc_collect_cycles();foreach($this->files as$p)if(is_file($p))unlink($p);parent::tearDown();}
 private function admin():int{return DB::table('users')->insertGetId(['name'=>'Administrator','student_id'=>'ADM'.bin2hex(random_bytes(8)),'password'=>Hash::make('valid-password'),'role'=>'admin','must_change_password'=>false]);}
 private function xlsx(array $rows):string{$dir=storage_path('app/imports');if(!is_dir($dir))mkdir($dir,0700,true);$path=$dir.'/test-'.Str::uuid().'.xlsx';$this->files[]=$path;$w=new Writer(new Options(tempFolder:$dir));$w->openToFile($path);foreach($rows as$row)$w->addRow(new Row(array_map(fn($v)=>$v instanceof \OpenSpout\Common\Entity\Cell?$v:new StringCell($v),$row)));$w->close();return $path;}
 private function failure(string $code,callable $fn):void{try{$fn();$this->fail('Expected '.$code);}catch(Failure $e){$this->assertSame($code,$e->errorCode);}}
 public function test_all_three_download_templates_are_real_xlsx_with_text_leading_zero_id():void{foreach(['zh-CN','en','uk']as$locale){$path=(new XlsxUsers)->template($locale);$this->files[]=$path;$this->assertSame('PK',substr(file_get_contents($path),0,2));$rows=(new XlsxUsers)->parse($path);$this->assertSame('000123456',$rows[0]['student_id']);$this->assertSame('new',$rows[0]['action']);$this->assertSame(2,$rows[0]['row']);}}
 public function test_preflight_preserves_rows_marks_formulas_numeric_ids_short_whitespace_and_duplicates():void{$file=$this->xlsx([['姓名','学号'],['A','000123456'],['',''],['Duplicate','000123456'],['Short','001'],['Numeric',new NumericCell(123456)],['Formula',new FormulaCell('=1+1')],['Whitespace','000 123'],['Іван','000999999']]);$rows=(new XlsxUsers)->parse($file);$this->assertSame([2,4,5,6,7,8,9],array_column($rows,'row'));$this->assertSame('000123456',$rows[0]['student_id']);$this->assertSame('import_duplicate_in_file',$rows[1]['errors'][0]['code']);$this->assertSame('import_student_id_invalid',$rows[2]['errors'][0]['code']);$this->assertSame('import_student_id_must_be_text',$rows[3]['errors'][0]['code']);$this->assertSame('import_formula_not_allowed',$rows[4]['errors'][0]['code']);$this->assertSame('import_student_id_invalid',$rows[5]['errors'][0]['code']);$this->assertSame('new',$rows[6]['action']);}
 public function test_active_content_and_xml_entities_are_rejected_before_reader():void{$file=$this->xlsx([['Name','Student ID'],['A','123456']]);$z=new ZipArchive();$z->open($file);$z->addFromString('xl/vbaProject.bin','macro');$z->close();$this->failure('import_active_content',fn()=>(new XlsxUsers)->parse($file));$file=$this->xlsx([['Name','Student ID'],['A','123456']]);$z=new ZipArchive();$z->open($file);$z->addFromString('xl/entity.xml','<!DOCTYPE x [<!ENTITY e SYSTEM "file:///private">]><x/>');$z->close();$this->failure('import_active_content',fn()=>(new XlsxUsers)->parse($file));}
 public function test_zip_bomb_limits_are_checked_before_extraction():void{$file=$this->xlsx([['Name','Student ID'],['A','123456']]);$z=new ZipArchive();$z->open($file);$z->addFromString('xl/large.xml',str_repeat('x',2097152));$z->close();$this->failure('import_zip_limits',fn()=>(new XlsxUsers)->parse($file));}
 public function test_multiple_sheets_and_wrong_headers_are_explicit_errors():void{$file=$this->xlsx([['Name','Student ID'],['A','123456']]);$z=new ZipArchive();$z->open($file);$xml=$z->getFromName('xl/workbook.xml');$z->addFromString('xl/workbook.xml',str_replace('</sheets>','<sheet name="Hidden" sheetId="2" r:id="rId99"/></sheets>',$xml));$z->close();$this->failure('import_single_sheet_required',fn()=>(new XlsxUsers)->parse($file));$file=$this->xlsx([['foo','bar'],['A','123456']]);$this->failure('import_headers_missing',fn()=>(new XlsxUsers)->parse($file));}
 public function test_row_limit_prevents_unbounded_batch():void{$rows=[['Name','Student ID']];for($i=0;$i<2001;$i++)$rows[]=['Person',sprintf('%09d',$i)];$file=$this->xlsx($rows);$this->failure('import_row_limit',fn()=>(new XlsxUsers)->parse($file));}
 public function test_preview_is_non_mutating_confirm_updates_only_name_and_is_idempotent():void{Queue::fake();$admin=$this->admin();$existing=$this->admin();$u=DB::table('users')->find($existing);$password=$u->password;$sid=$this->sid();$file=$this->xlsx([['Name','Student ID'],['Renamed',$u->student_id],['New',$sid],['Error','123']]);$s=new UserImports;$preview=$s->preview($file,$admin,'update_name');$id=$preview['import']['id'];$this->assertEquals(['new'=>1,'update'=>1,'skip'=>0,'error'=>1],$preview['import']['counts']);$this->assertDatabaseMissing('users',['student_id'=>$sid]);$this->assertSame($u->name,DB::table('users')->find($existing)->name);$confirmed=$s->confirm($id,$admin,$preview['import']['preview_hash']);$this->assertSame('processing',$confirmed['import']['status']);(new ConfirmImport($id))->handle($s);$done=$s->show($id,$admin);$this->assertSame('completed',$done['import']['status']);$updated=DB::table('users')->find($existing);$this->assertSame('Renamed',$updated->name);$this->assertSame($password,$updated->password);$this->assertSame('admin',$updated->role);$this->assertFalse($updated->must_change_password);$new=DB::table('users')->where('student_id',$sid)->first();$this->assertTrue(Hash::check(mb_substr($sid,-6),$new->password));$this->assertTrue($new->must_change_password);$this->assertSame('user',$new->role);$s->confirm($id,$admin,$preview['import']['preview_hash']);(new ConfirmImport($id))->handle($s);$this->assertSame(1,DB::table('users')->where('student_id',$sid)->count());$this->assertSame(1,DB::table('audit')->where('action','users.imported')->where('user_id',$admin)->count());}
 public function test_default_skip_duplicate_import_preserves_password_role_and_force_flag():void{Queue::fake();$admin=$this->admin();$existing=DB::table('users')->find($admin);$file=$this->xlsx([['名字','学号'],['Changed',$existing->student_id]]);$s=new UserImports;$p=$s->preview($file,$admin);$this->assertSame(1,$p['import']['counts']['skip']);$s->confirm($p['import']['id'],$admin,$p['import']['preview_hash']);$s->execute($p['import']['id']);$u=DB::table('users')->find($admin);$this->assertSame($existing->name,$u->name);$this->assertSame($existing->password,$u->password);$this->assertSame('admin',$u->role);$this->assertFalse($u->must_change_password);}
 public function test_import_owner_hash_and_expiry_are_verified_and_no_wrong_admin_execution():void{Queue::fake();$admin=$this->admin();$other=$this->admin();$sid=$this->sid();$s=new UserImports;$p=$s->preview($this->xlsx([['Name','Student ID'],['A',$sid]]),$admin);$id=$p['import']['id'];$this->failure('import_unavailable',fn()=>$s->show($id,$other));$this->failure('import_unavailable',fn()=>$s->confirm($id,$other,$p['import']['preview_hash']));$this->failure('import_preview_changed',fn()=>$s->confirm($id,$admin,str_repeat('0',64)));DB::table('user_imports')->where('id',$id)->update(['expires_at'=>now()->subSecond()]);$this->failure('import_expired',fn()=>$s->confirm($id,$admin,$p['import']['preview_hash']));$this->assertDatabaseMissing('users',['student_id'=>$sid]);}
 public function test_worker_revalidates_admin_authority_and_failed_hook_marks_whole_batch():void{Queue::fake();$admin=$this->admin();$sid=$this->sid();$sid2=$this->sid();$s=new UserImports;$p=$s->preview($this->xlsx([['Name','Student ID'],['A',$sid],['B',$sid2]]),$admin);$id=$p['import']['id'];$s->confirm($id,$admin,$p['import']['preview_hash']);DB::table('users')->where('id',$admin)->update(['disabled'=>true]);$this->failure('login_required',fn()=>$s->execute($id));$this->assertDatabaseMissing('users',['student_id'=>$sid]);$this->assertDatabaseMissing('users',['student_id'=>$sid2]);(new ConfirmImport($id))->failed(new \RuntimeException('fixture'));$this->assertSame('failed',$s->show($id,$admin)['import']['status']);}
 public function test_errors_csv_prevents_formula_injection_and_keeps_original_line():void{$admin=$this->admin();$s=new UserImports;$p=$s->preview($this->xlsx([['Name','Student ID'],['=HYPERLINK("bad")','123']]),$admin);$file=$s->errorsCsv($p['import']['id'],$admin);$this->files[]=$file;$f=fopen($file,'rb');fgetcsv($f,escape:'');$row=fgetcsv($f,escape:'');fclose($f);$this->assertSame('2',$row[0]);$this->assertSame("'=HYPERLINK(\"bad\")",$row[1]);$this->assertSame('123',$row[2]);$this->assertStringContainsString('import_student_id_invalid',$row[3]);}
 public function test_http_template_is_downloadable_and_confirm_requires_recent_auth():void{$admin=$this->admin();$this->withSession(['uid'=>$admin])->get('/api/admin/users/template.xlsx?locale=uk')->assertOk()->assertDownload('users-template.xlsx');$p=(new UserImports)->preview($this->xlsx([['Name','Student ID'],['A','123456']]),$admin);$this->withSession(['uid'=>$admin])->postJson('/api/admin/imports/'.$p['import']['id'].'/confirm',['preview_hash'=>$p['import']['preview_hash'],'confirm'=>true])->assertStatus(403)->assertJsonPath('code','reauth_required');}
 public function test_real_http_xlsx_upload_is_preview_only_and_download_is_private():void{$admin=$this->admin();$sid=$this->sid();$path=$this->xlsx([['Name','Student ID'],['Іван',$sid]]);$file=new \Illuminate\Http\UploadedFile($path,'users.xlsx',test:true);$response=$this->withSession(['uid'=>$admin])->post('/api/admin/imports',['file'=>$file],['Accept'=>'application/json'])->assertOk()->assertJsonPath('import.status','preview')->assertJsonPath('rows.0.student_id',$sid);$this->assertDatabaseMissing('users',['student_id'=>$sid]);$id=$response->json('import.id');$download=$this->get('/api/admin/imports/'.$id.'/errors.csv')->assertOk()->assertDownload('import-errors.csv');$this->assertStringContainsString('no-store',$download->headers->get('Cache-Control'));$this->assertStringContainsString('private',$download->headers->get('Cache-Control'));}
 public function test_unicode_whitespace_is_normalized_and_empty_name_rejected():void{$rows=(new XlsxUsers)->parse($this->xlsx([['Name','Student ID'],["\u{00a0}","000123456"],["\u{3000}Іван\u{00a0}","\u{00a0}000999999\u{3000}"]]));$this->assertSame('import_name_invalid',$rows[0]['errors'][0]['code']);$this->assertSame('Іван',$rows[1]['name']);$this->assertSame('000999999',$rows[1]['student_id']);$this->assertSame('new',$rows[1]['action']);}
 public function test_admin_upload_limits_apply_to_new_previews_without_changing_accepted_snapshot():void {Queue::fake();$a=DB::table('users')->find($this->admin());$file=$this->xlsx([['Name','Student ID'],['A',$this->sid()],['B',$this->sid()]]);$service=new UserImports;$preview=$service->preview($file,$a->id);\App\Settings\Settings::save('policies',['max_import_rows'=>1],\App\Settings\Settings::version('policies'),$a);$this->failure('import_row_limit',fn()=>$service->preview($file,$a->id));$service->confirm($preview['import']['id'],$a->id,$preview['import']['preview_hash']);$service->execute($preview['import']['id']);$this->assertSame(2,$service->show($preview['import']['id'],$a->id)['import']['counts']['new']);$this->failure('settings_values_invalid',fn()=>\App\Settings\Settings::save('policies',['max_import_bytes'=>4194305],\App\Settings\Settings::version('policies'),$a));}
}
